import re
def answerable(q):
    return len(q.split()) >= 5 and bool(re.search(r'\d|which|what|how', q, re.I))
for q in ['search stuff', 'What latencies do inverted indexes achieve at 50k records?']:
    print(('ANSWERABLE ' if answerable(q) else 'REFINE ') + q[:50])

